function matchJob_(text) {
  const t = String(text || '');
  const ot = t.indexOf('작업치료') > -1;
  const pt = t.indexOf('물리치료') > -1;
  /* 둘 다 적힌 공고가 있습니다. 통합 채용이나 '작업치료사 또는 물리치료사'
     같은 자격 조건이 그렇습니다. 한쪽으로 단정하면 나머지 직군은
     자기 공고를 못 봅니다. 그럴 때는 양쪽에 다 보여줍니다. */
  if (ot && pt) return '공통';
  if (ot) return '작업치료사';
  if (pt) return '물리치료사';
  /* 재활치료·언어치료처럼 두 직군 모두 지원할 수 있는 말 */
  for (let i = 0; i < JOB_WORDS.length; i++) {
    if (t.indexOf(JOB_WORDS[i]) > -1) return '공통';
  }
  return '';
}
function notOurs_(title) {
  const t = String(title || '');
  /* 제목에 우리 직군이 함께 적혀 있으면 통합 채용이므로 받습니다 */
  if (t.indexOf('작업치료') > -1 || t.indexOf('물리치료') > -1) return false;
  /* 여러 자리를 함께 뽑는 공고는 「보건직」 같은 묶음 안에
     우리 직군이 숨어 있을 수 있어 버리지 않습니다. */
  if (multiRole_(t)) return false;
  for (let i = 0; i < NOT_OURS.length; i++) {
    if (t.indexOf(NOT_OURS[i]) > -1) return true;
  }
  return false;
}
function multiRole_(title) {
  const t = String(title || '');
  if (/공개채용|공채|신규직원|일괄|분야별|통합채용|직렬별|각 ?분야/.test(t)) return true;
  /* 괄호 안에 자리가 둘 이상 나열돼 있으면 통합입니다 */
  const groups = t.match(/[(\uFF08][^)\uFF09]*[)\uFF09]?/g) || [];
  for (let i = 0; i < groups.length; i++) {
    const inner = groups[i].replace(/[(\uFF08)\uFF09]/g, '');
    const parts = inner.split(/[,\u3001\u00B7\u318D\/]|\s및\s|\s외\s/)
      .map(function (x) { return x.trim(); }).filter(String);
    if (parts.length >= 2) return true;
  }
  return false;
}
function mixedTitle_(title) {
  const t = String(title || '');
  const groups = t.match(/[(\uFF08][^)\uFF09]*[)\uFF09]/g) || [];
  for (let i = 0; i < groups.length; i++) {
    const inner = groups[i].replace(/[(\uFF08)\uFF09]/g, '');
    if (inner.indexOf('작업치료') < 0 && inner.indexOf('물리치료') < 0) continue;
    const parts = inner.split(/[,\u3001\u00B7\u318D\/]|\s및\s|\s외\s/)
      .map(function (x) { return x.trim(); })
      .filter(String);
    if (parts.length < 2) continue;
    for (let k = 0; k < parts.length; k++) {
      if (parts[k].indexOf('작업치료') < 0 && parts[k].indexOf('물리치료') < 0) return true;
    }
  }
  return false;
}
function titleOtherOnly_(title) {
  const t = String(title || '');
  return OTHER_PROF_RE.test(t) && !OUR_PROF_RE.test(t);
}
function fmtDate_(v) {
  const s = String(v || '').replace(/[^0-9]/g, '');
  if (s.length === 8) return s.slice(0, 4) + '.' + s.slice(4, 6) + '.' + s.slice(6, 8);
  return String(v || '');
}
function hospVerdict_(title, org) {
  title = String(title || '');
  if (HS_SKIP_RE.test(title)) return '버림(결과·안내 글)';
  /* 「보건직」 「의료기술직」 「재활」 이 든 통합 공고는 남의 직군이 같이 적혀 있어도 우리 자리가 들어 있을 수 있어 사람이 봅니다
     (부산대 「일반직(행정, 보건, 간호조무, 원무직) 신규직원 공개채용」)
     기관 이름은 빼고 봅니다 — 「국립교통재활병원 언어치료사」 의 「재활」 은 병원 이름입니다 (2026-09-12) */
  const bare = org ? title.split(String(org)).join(' ').replace(/재활병원|재활의학|재활원/g, ' ') : title;
  const broad = HS_BROAD_RE.test(bare);
  if (titleOtherOnly_(title) && !broad) return '버림(남의 직군)';
  const job = matchJob_(title);
  if (job) return '담음(' + job + ')';
  if (broad) return '보류(보건직·의료기술직 포함)';
  /* 의사·전공의·교수·약사·연구원·기사… 병원에서만 나오는 남의 자리 */
  if (HS_OTHER_RE.test(title)) return '버림(' + (title.match(HS_OTHER_RE) || [''])[0] + ')';
  if (multiRole_(title) || /직원|채용\s*공고|모집\s*공고|공개\s*채용|계약직|기간제|대체|임시직|정규직|채용\s*안내|모집\s*안내/.test(title)) return '보류(직군 확인)';
  return '버림(우리 직군 아님)';
}
